<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { PhArrowSquareOut, PhCheckCircle, PhFlask, PhListPlus, PhPlay, PhPlus, PhTrash, PhWarningCircle, PhXCircle } from '@phosphor-icons/vue';
import { createWebEvaluation, createWebEvaluationCase, deleteWebEvaluation, deleteWebEvaluationCase, listWebEvaluationCases, listWebEvaluations, subscribeToWebEvaluation } from '../api/evaluations';
import type { WebEvaluation, WebEvaluationCase, WebEvaluationMetrics } from '../types/evaluations';

const cases = ref<WebEvaluationCase[]>([]), runs = ref<WebEvaluation[]>([]), selectedIds = ref<string[]>([]);
const activeId = ref(''), baselineId = ref(''), detailId = ref(''), error = ref('');
const loading = ref(true), launching = ref(false), showCreator = ref(false), savingCase = ref(false);
const form = ref({ title: '', question: '', answerable: true, domains: '', needs: '' });
let unsubscribe: (() => void) | undefined;
const active = computed(() => runs.value.find(x => x.id === activeId.value));
const baseline = computed(() => runs.value.find(x => x.id === baselineId.value));
const detail = computed(() => active.value?.report?.cases.find(x => x.id === detailId.value) ?? active.value?.report?.cases[0]);
const running = computed(() => ['queued', 'running'].includes(active.value?.status ?? ''));
const anyRunning = computed(() => runs.value.some(x => ['queued', 'running'].includes(x.status)));
const baselines = computed(() => runs.value.filter(x => x.id !== activeId.value && x.status === 'completed'));
const metrics = computed(() => active.value?.report?.metrics);
const customCases = computed(() => cases.value.filter(x => x.custom));
const deltas = computed(() => {
  const a = metrics.value, b = baseline.value?.report?.metrics;
  if (!a || !b) return [];
  const fields: Array<[keyof WebEvaluationMetrics, string, boolean?]> = [
    ['hitAtK', 'Hit@K'], ['mrr', 'MRR'], ['evidencePrecision', '证据精确率'],
    ['evidenceRecall', '问题覆盖率'], ['passRate', '通过率'], ['falseSufficientRate', '误判充分率', true]
  ];
  return fields.map(([key, label, lower]) => { const delta = Number(a[key]) - Number(b[key]); return { key, label, delta, good: lower ? delta < 0 : delta > 0 }; });
});

onMounted(async () => { try { await reload(); } catch (e) { error.value = msg(e); } finally { loading.value = false; } });
onUnmounted(() => unsubscribe?.());
async function reload() { const [c, r] = await Promise.all([listWebEvaluationCases(), listWebEvaluations()]); cases.value = c.cases; if (!selectedIds.value.length) selectedIds.value = c.cases.map(x => x.id); runs.value = r.evaluations; if (runs.value[0] && !activeId.value) selectRun(runs.value[0]); }
async function launch() { if (!selectedIds.value.length || anyRunning.value) return; launching.value = true; error.value = ''; try { const { evaluation } = await createWebEvaluation({ caseIds: selectedIds.value, k: 3 }); runs.value.unshift(evaluation); selectRun(evaluation); } catch (e) { error.value = msg(e); } finally { launching.value = false; } }
function selectRun(run: WebEvaluation) { activeId.value = run.id; detailId.value = run.report?.cases[0]?.id ?? ''; baselineId.value = ''; unsubscribe?.(); unsubscribe = undefined; if (['queued', 'running'].includes(run.status)) unsubscribe = subscribeToWebEvaluation(run.id, event => { const i = runs.value.findIndex(x => x.id === event.evaluation.id); if (i >= 0) runs.value[i] = event.evaluation; if (event.evaluation.report && !detailId.value) detailId.value = event.evaluation.report.cases[0]?.id ?? ''; }, () => error.value = '实时进度连接已中断，请刷新查看结果。'); }
async function remove(run: WebEvaluation) { try { await deleteWebEvaluation(run.id); runs.value = runs.value.filter(x => x.id !== run.id); if (activeId.value === run.id) { activeId.value = ''; if (runs.value[0]) selectRun(runs.value[0]); } } catch (e) { error.value = msg(e); } }
async function saveCase() { savingCase.value = true; error.value = ''; try { const domains = split(form.value.domains); const { case: saved } = await createWebEvaluationCase({ title: form.value.title, question: form.value.question, answerable: form.value.answerable, includeDomains: domains, expectedDomains: domains, evidenceNeeds: split(form.value.needs) }); cases.value.push(saved); selectedIds.value.push(saved.id); form.value = { title: '', question: '', answerable: true, domains: '', needs: '' }; showCreator.value = false; } catch (e) { error.value = msg(e); } finally { savingCase.value = false; } }
async function removeCase(item: WebEvaluationCase) { try { await deleteWebEvaluationCase(item.id); cases.value = cases.value.filter(x => x.id !== item.id); selectedIds.value = selectedIds.value.filter(x => x !== item.id); } catch (e) { error.value = msg(e); } }
function toggle(id: string) { selectedIds.value = selectedIds.value.includes(id) ? selectedIds.value.filter(x => x !== id) : [...selectedIds.value, id]; }
function split(value: string) { return value.split(/[，,;；\n]/).map(x => x.trim()).filter(Boolean); }
const pct = (n: number) => `${Math.round(n * 100)}%`, time = (n: number) => n < 1000 ? `${n} ms` : `${(n / 1000).toFixed(1)} s`, date = (s: string) => new Date(s).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }), msg = (e: unknown) => e instanceof Error ? e.message : '操作失败';
</script>

<template>
  <div class="shell">
    <aside class="rail"><div class="rail-title">运行记录 <b>{{ runs.length }}</b></div><p v-if="!runs.length && !loading" class="muted">首次运行后，结果会保存在这里。</p>
      <div v-for="run in runs" :key="run.id" class="run" :class="{ active: run.id === activeId }" role="button" tabindex="0" @click="selectRun(run)" @keydown.enter="selectRun(run)"><i :class="run.status"/><span><strong>{{ run.name }}</strong><small>{{ date(run.createdAt) }} · {{ run.completedCases }}/{{ run.totalCases }}</small></span><button v-if="['completed','failed'].includes(run.status)" title="删除" @click.stop="remove(run)"><PhTrash :size="14"/></button></div>
    </aside>
    <main class="lab-scroll">
      <header><div><label><PhFlask :size="15" weight="fill"/> WEB RETRIEVAL LAB</label><h1>联网检索实验台</h1><p>把每个问题拆成可核验的证据点，判断“检索到了”是否等于“回答得住”。</p></div><button class="primary" :disabled="launching || !selectedIds.length || anyRunning" @click="launch"><PhPlay :size="17" weight="fill"/>{{ anyRunning ? '评测运行中' : `运行 ${selectedIds.length} 道题` }}</button></header>
      <div v-if="error" class="error"><PhWarningCircle :size="18"/>{{ error }}</div>
      <section v-if="running" class="progress"><div><strong>正在验证 {{ active?.currentCaseId || '问题集' }}</strong><span>{{ active?.completedCases }}/{{ active?.totalCases }}</span></div><div class="track"><i :style="{ width: pct((active?.completedCases ?? 0) / Math.max(active?.totalCases ?? 1, 1)) }"/></div><small>顺序调用真实联网检索，避免并发放大 API credits 消耗。</small></section>
      <section><div class="section-head"><div><strong>回归基线与自定义题</strong><small>固定题保证前后可比；自定义题验证你的真实业务问题。</small></div><div class="head-actions"><button class="outline" @click="showCreator = !showCreator"><PhPlus :size="15"/>添加自定义题</button><button class="link" @click="selectedIds = selectedIds.length === cases.length ? [] : cases.map(x => x.id)">{{ selectedIds.length === cases.length ? '清空' : '全选' }}</button></div></div>
        <form v-if="showCreator" class="creator" @submit.prevent="saveCase"><div class="creator-title"><PhListPlus :size="18"/><strong>添加自定义评测题</strong><small>证据点用逗号分隔；每个证据点可以用“同义词 A, 同义词 B”表示匹配词。</small></div><div class="form-grid"><label>题目名称<input v-model="form.title" required maxlength="80" placeholder="例如：OpenAI Responses API"/></label><label class="wide">问题内容<textarea v-model="form.question" required maxlength="1000" placeholder="写入希望验证的完整问题，例如：某个参数的可选值、约束和官方定价。"/></label><label>官方域名<input v-model="form.domains" :required="form.answerable" placeholder="例如：platform.openai.com"/></label><label>证据点<input v-model="form.needs" :required="form.answerable" placeholder="例如：参数名, 可选值, 定价"/></label><label class="check"><input v-model="form.answerable" type="checkbox"/>这是可回答的问题</label></div><div class="creator-actions"><button type="button" class="outline" @click="showCreator = false">取消</button><button class="primary" :disabled="savingCase">{{ savingCase ? '保存中…' : '保存并加入本次运行' }}</button></div></form>
        <div class="questions"><button v-for="item in cases" :key="item.id" :class="{ selected: selectedIds.includes(item.id), custom: item.custom }" @click="toggle(item.id)"><PhCheckCircle :size="19" :weight="selectedIds.includes(item.id) ? 'fill' : 'regular'"/><span><strong>{{ item.title }} <em v-if="item.custom">自定义</em></strong><small>{{ item.answerable ? '可回答' : '不可回答' }} · {{ item.evidenceNeeds.length }} 个证据点 · {{ item.expectedDomains.join(', ') || '不限定域名' }}</small></span><button v-if="item.custom" class="remove-case" title="删除自定义题" @click.stop="removeCase(item)"><PhTrash :size="14"/></button></button></div>
        <p v-if="customCases.length" class="muted custom-note">自定义题会持久化保存；固定基线题不可删除，以保证历史评测可比。</p>
      </section>
      <template v-if="metrics && active?.report"><div class="metric-grid"><article><small>Hit@{{ active.report.k }}</small><b>{{ pct(metrics.hitAtK) }}</b><span>前 K 条出现有效来源</span></article><article><small>MRR</small><b>{{ metrics.mrr.toFixed(2) }}</b><span>有效来源越靠前越好</span></article><article><small>证据精确率</small><b>{{ pct(metrics.evidencePrecision) }}</b><span>返回来源中有效的比例</span></article><article><small>问题覆盖率</small><b>{{ pct(metrics.evidenceRecall) }}</b><span>预期事实点被覆盖比例</span></article><article><small>用例通过率</small><b>{{ pct(metrics.passRate) }}</b><span>{{ metrics.caseCount }} 道问题的严格通过率</span></article><article :class="{ danger: metrics.falseSufficientCount }"><small>误判充分</small><b>{{ metrics.falseSufficientCount }}</b><span>系统说充分但证据不够</span></article></div>
        <section><div class="section-head"><div><strong>与历史运行对比</strong><small>选择一份基线，检查优化是否带来实际提升。</small></div><select v-model="baselineId"><option value="">选择基线运行</option><option v-for="run in baselines" :key="run.id" :value="run.id">{{ run.name }}</option></select></div><div v-if="deltas.length" class="deltas"><div v-for="d in deltas" :key="d.key"><small>{{ d.label }}</small><b :class="d.delta === 0 ? 'flat' : d.good ? 'good' : 'bad'">{{ d.delta > 0 ? '+' : '' }}{{ pct(d.delta) }}</b></div></div><p v-else class="muted">完成至少两次运行后，可在这里比较策略变化。</p></section>
        <section><div class="section-head"><div><strong>逐题结果</strong><small>选择题目，向下查看完整的证据覆盖、查询轨迹和来源。</small></div><span class="muted">平均 {{ metrics.avgQueryCount.toFixed(1) }} 次查询 / {{ metrics.avgPageCount.toFixed(1) }} 页</span></div><div class="results"><button v-for="item in active.report.cases" :key="item.id" :class="{ active: detail?.id === item.id }" @click="detailId = item.id"><component :is="item.passed ? PhCheckCircle : PhXCircle" :class="item.passed ? 'good' : 'bad'" :size="19" weight="fill"/><span><strong>{{ item.title }}</strong><small>{{ item.verdict }} · {{ item.queryCount }} 次查询 · {{ time(item.durationMs) }}</small></span><div><small>问题覆盖</small><i class="track"><i :style="{ width: pct(item.evidenceRecall) }"/></i><b>{{ pct(item.evidenceRecall) }}</b></div><em v-if="item.falseSufficient">误判充分</em></button></div></section>
        <section v-if="detail" class="detail"><div class="detail-title"><div><label>{{ detail.id }}</label><h2>{{ detail.question }}</h2></div><b>{{ detail.verdict }}</b></div><div class="detail-grid"><div><h3>问题覆盖</h3><p v-if="!detail.supportedNeeds.length" class="muted">不可回答用例：预期系统不判定为充分。</p><p v-for="need in detail.supportedNeeds" :key="need.id" class="need" :class="need.supported ? 'good' : 'bad'"><component :is="need.supported ? PhCheckCircle : PhXCircle" :size="18" weight="fill"/>{{ need.label }}</p><h3>查询轨迹</h3><ol><li v-for="q in detail.retrievalQueries" :key="q">{{ q }}</li></ol><p class="stop"><b>停止原因：</b>{{ detail.stopReason }}</p></div><div><h3>返回来源</h3><p v-if="!detail.retrieved.length" class="muted">没有形成可用 Web Source。</p><article v-for="s in detail.retrieved" :key="s.url" class="source" :class="{ relevant: s.relevant }"><b>{{ s.rank }}</b><span><strong>{{ s.title }}</strong><small>{{ s.domain }} · score {{ s.score.toFixed(2) }}<template v-if="s.supportedNeedIds.length"> · 支持 {{ s.supportedNeedIds.join(', ') }}</template></small></span><a :href="s.url" target="_blank" rel="noreferrer"><PhArrowSquareOut :size="17"/></a></article></div></div></section>
      </template><div v-else-if="!loading && !running" class="welcome"><PhFlask :size="28"/><h2>运行第一次基线评测</h2><p>结果会同时显示检索命中、证据精确率、问题覆盖率与误判充分。</p></div>
    </main>
  </div>
</template>

<style scoped>
.shell{display:grid;grid-template-columns:245px minmax(0,1fr);height:100%;min-height:0;background:var(--agent-bg,#f7f7f5);color:var(--agent-text,#222)}.rail,.lab-scroll{min-height:0;overflow:auto}.rail{padding:18px 12px;border-right:1px solid var(--agent-border,#ddd);background:var(--agent-surface,#fff)}.rail-title{display:flex;justify-content:space-between;padding:0 8px 12px;font-size:12px;font-weight:800;text-transform:uppercase}.rail-title b{color:#777}.run{display:flex;width:100%;align-items:center;gap:9px;border:1px solid transparent;border-radius:8px;background:none;color:inherit;padding:10px 8px;text-align:left;cursor:pointer}.run.active,.run:hover{border-color:var(--agent-border,#ddd);background:var(--agent-surface-muted,#f1f1ed)}.run>i{width:8px;height:8px;border-radius:50%;background:#aaa}.run>i.completed{background:#238455}.run>i.running,.run>i.queued{background:#d68b19}.run>i.failed{background:#bd3d32}.run>span{display:flex;min-width:0;flex:1;flex-direction:column}.run strong{font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.run small,.muted{font-size:11px;color:var(--agent-text-muted,#777)}.run>button,.remove-case{border:0;background:none;color:#999;cursor:pointer}.lab-scroll{padding:28px clamp(18px,3vw,44px) 60px}header{display:flex;justify-content:space-between;align-items:flex-start;gap:22px;margin-bottom:22px}header label{display:flex;align-items:center;gap:6px;font-size:11px;font-weight:900;letter-spacing:.15em;color:#277459}h1{margin:6px 0 3px;font-size:30px;letter-spacing:-.04em}header p{margin:0;color:#6b6d67;font-size:14px}.primary,.outline{display:inline-flex;gap:8px;align-items:center;border-radius:7px;padding:9px 13px;font-weight:750;cursor:pointer}.primary{border:1px solid #1f6049;background:#246f53;color:white}.primary:disabled{opacity:.45}.outline{border:1px solid var(--agent-border,#ccc);background:transparent;color:var(--agent-text,#222)}.error,.progress{border:1px solid #d9a9a3;border-radius:8px;background:#fff5f3;padding:12px 14px;margin-bottom:16px}.error{display:flex;gap:8px;color:#96362e}.progress{border-color:#dec693;background:#fffbef}.progress>div:first-child,.section-head{display:flex;justify-content:space-between;align-items:center;gap:14px}.progress small{font-size:11px;color:#7b704e}.track{display:block;height:6px;border-radius:9px;background:#e5e5df;overflow:hidden}.progress>.track{margin:9px 0 6px}.track i{display:block;height:100%;background:#277459}section{border:1px solid var(--agent-border,#ddd);border-radius:10px;background:var(--agent-surface,#fff);padding:18px;margin-bottom:18px}.section-head>div{display:flex;flex-direction:column}.section-head strong{font-size:14px}.section-head small{font-size:11px;color:#777;margin-top:3px}.head-actions{display:flex;align-items:center;gap:9px}.link{border:0;background:none;color:#277459;font-weight:700;cursor:pointer}.creator{border:1px dashed #78aa93;background:#f6fbf8;border-radius:8px;padding:14px;margin-top:14px}.creator-title{display:grid;grid-template-columns:auto auto 1fr;align-items:center;gap:8px;color:#277459}.creator-title small{color:#68776f;font-size:11px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:12px}.form-grid label{display:flex;flex-direction:column;gap:5px;font-size:11px;font-weight:700;color:#555}.form-grid .wide{grid-column:span 2}.form-grid input,.form-grid textarea,select{border:1px solid #cfd4cc;border-radius:6px;background:#fff;color:inherit;padding:8px;font:inherit;font-size:12px}.form-grid textarea{min-height:64px;resize:vertical}.form-grid .check{align-self:end;flex-direction:row;align-items:center;gap:7px}.creator-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:12px}.questions{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:8px;margin-top:13px}.questions>button{display:flex;gap:8px;align-items:flex-start;border:1px solid var(--agent-border,#ddd);border-radius:7px;background:none;color:inherit;padding:10px;text-align:left;cursor:pointer}.questions>button.selected{border-color:#6fa88f;background:#f0f7f3;color:#277459}.questions>button.custom{border-left:3px solid #d59b38}.questions span{display:flex;min-width:0;flex:1;flex-direction:column}.questions strong{font-size:13px;color:var(--agent-text,#222)}.questions em{font-size:9px;font-style:normal;color:#8a641e;background:#fff3d9;border-radius:3px;padding:2px 4px;margin-left:4px}.questions small{margin-top:4px;font-size:10px;color:#777;line-height:1.4}.custom-note{margin:12px 0 0}.metric-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:9px;margin-bottom:18px}.metric-grid article{border-top:3px solid #277459;border-radius:3px 3px 8px 8px;background:var(--agent-surface,#fff);box-shadow:0 0 0 1px var(--agent-border,#ddd);padding:13px}.metric-grid article.danger{border-color:#bd3d32}.metric-grid small,.metric-grid span{display:block;font-size:10px;color:#777}.metric-grid b{display:block;font-size:24px;margin:4px 0}.deltas{display:grid;grid-template-columns:repeat(6,1fr);gap:9px;margin-top:14px}.deltas div{border-left:2px solid #ddd;padding-left:9px}.deltas small,.deltas b{display:block;font-size:11px}.deltas b{font-size:16px;margin-top:3px}.good{color:#238455}.bad{color:#bd3d32}.flat{color:#777}.results{margin-top:12px}.results>button{display:grid;grid-template-columns:25px minmax(160px,1fr) minmax(160px,250px) auto;align-items:center;gap:10px;width:100%;border:0;border-top:1px solid var(--agent-border,#ddd);background:none;color:inherit;padding:11px 7px;text-align:left;cursor:pointer}.results>button.active{background:var(--agent-surface-muted,#f3f3ef)}.results>button>span{display:flex;flex-direction:column}.results small{font-size:10px;color:#777}.results>button>div{display:grid;grid-template-columns:55px 1fr 34px;align-items:center;gap:7px}.results em{font-style:normal;font-size:10px;color:#a43d32;background:#fae9e7;padding:4px 6px;border-radius:9px}.detail-title{display:flex;justify-content:space-between;border-bottom:1px solid #ddd;padding-bottom:14px}.detail-title label{font:700 10px monospace;color:#277459}.detail-title h2{font-size:16px;line-height:1.5;margin:4px 0 0}.detail-title>b{font-size:11px}.detail-grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:28px;padding-top:16px}.detail-grid h3{font-size:11px;text-transform:uppercase;letter-spacing:.08em;margin:0 0 9px}.detail-grid h3:not(:first-child){margin-top:20px}.need{display:flex;align-items:center;gap:7px;font-size:13px}.detail-grid ol{padding-left:20px;font-size:11px;color:#666}.stop{border-left:2px solid #d4b46e;padding-left:9px;font-size:11px;color:#666}.source{display:grid;grid-template-columns:23px 1fr 18px;gap:8px;border:1px solid #ddd;border-left:3px solid #aaa;border-radius:6px;padding:9px;margin-bottom:7px}.source.relevant{border-left-color:#277459}.source>b{display:grid;place-items:center;width:21px;height:21px;border-radius:50%;background:#eee;font-size:10px}.source>span{display:flex;min-width:0;flex-direction:column}.source strong{font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.source small{font-size:9px;color:#777}.source a{color:#277459}.welcome{text-align:center;border:1px dashed #ccc;border-radius:10px;padding:48px;color:#777}.welcome h2{font-size:17px;color:var(--agent-text,#222);margin:10px 0 4px}.welcome p{font-size:12px;margin:0}@media(max-width:1050px){.metric-grid{grid-template-columns:repeat(3,1fr)}.deltas{grid-template-columns:repeat(3,1fr)}}@media(max-width:720px){.shell{grid-template-columns:1fr}.rail{display:none}.lab-scroll{padding:20px 13px}header{flex-direction:column}.metric-grid{grid-template-columns:repeat(2,1fr)}.detail-grid,.form-grid{grid-template-columns:1fr}.form-grid .wide{grid-column:auto}.results>button{grid-template-columns:25px 1fr}.results>button>div,.results em{grid-column:2}}
</style>
